// Counter has a data race — no mutex on concurrent increment.
type Counter struct {
	value int // BUG: not protected by mutex
}

func (c *Counter) Increment() {
	c.value++ // BUG: data race when called concurrently
}

func (c *Counter) Value() int {
	return c.value // BUG: unsynchronized read
}

