// FindFirst returns the first element matching predicate.
// BUG: nil deref — doesn't check if slice is nil before accessing.
func FindFirst(items []string, pred func(string) bool) *string {
	for _, item := range items {
		if pred(item) {
			return &item // BUG: returns pointer to loop var (stale after loop)
		}
	}
	return nil
}

// SumPositive should sum only positive numbers.
// BUG: logic error — sums all numbers, ignores the positive-only requirement.
func SumPositive(nums []int) int {
	total := 0
	for _, n := range nums {
		total += n // BUG: should only add if n > 0
	}
	return total
