package bugs_test

import (
	"sync"
	"testing"

	"github.com/ai-verification/multi-bug/bugs"
)

func TestSafeCounterConcurrent(t *testing.T) {
	c := &bugs.SafeCounter{}
	var wg sync.WaitGroup
	for i := 0; i < 100; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			c.Increment()
		}()
	}
	wg.Wait()
	if c.Value() != 100 {
		t.Fatalf("expected 100, got %d", c.Value())
	}
}

func TestFindFirst(t *testing.T) {
	items := []string{"apple", "banana", "cherry"}
	result := bugs.FindFirst(items, func(s string) bool { return s == "banana" })
	if result == nil {
		t.Fatal("expected non-nil result")
	}
	if *result != "banana" {
		t.Fatalf("expected banana, got %s", *result)
	}
}

func TestFindFirstNotFound(t *testing.T) {
	result := bugs.FindFirst([]string{"a", "b"}, func(s string) bool { return s == "z" })
	if result != nil {
		t.Fatal("expected nil when not found")
	}
}

func TestSumPositive(t *testing.T) {
	result := bugs.SumPositive([]int{1, -2, 3, -4, 5})
	if result != 9 {
		t.Fatalf("expected 9, got %d", result)
	}
}

func TestSumPositiveAllNegative(t *testing.T) {
	result := bugs.SumPositive([]int{-1, -2, -3})
	if result != 0 {
		t.Fatalf("expected 0, got %d", result)
	}
}
